--- from:  > name: OverseaManageVipOrderTips
---@class TakeoutVipOrderPopup
---@field Env                           	TakeoutVipOrderPopup
---@field controller                    	Engine.UI.UILuaDialog
---@field BtnCookMake                   	UnityEngine.RectTransform
---@field CommonBtnConsumePop           	UnityEngine.RectTransform
---@field CookGoodNode                  	UnityEngine.RectTransform
---@field TextTitle                     	UnityEngine.UI.Text
---@field TextName                      	UnityEngine.UI.Text
---@field TextNumber                    	TMPro.TextMeshProUGUI
---@field GoodNode                      	UnityEngine.RectTransform
---@field FontStyleButton               	UnityEngine.RectTransform
---@field BtnCookMake                       UnityEngine.RectTransform

local TakeoutVipOrderPopup = Class("TakeoutVipOrderPopup")
local MaidCoffeeConstants = import("Game.MaidCoffee.MaidCoffeeConstants")
function TakeoutVipOrderPopup:__init()
    self.data = nil
    self.EventEveryThingChangeEventName = nil
end

function TakeoutVipOrderPopup:__delete()
    self.data = nil
    self.EventEveryThingChangeEventName = nil
    self.controller = nil
end

function TakeoutVipOrderPopup:Awake()
    SetButtonAction(self.FontStyleButton, function()
        ---提示资源的逻辑
        ---添加奖励显示的逻辑
        ---@type CookOrderDojo
        local cookOrderDojo = self.data
        local goodsVo = GoodsConfMgr:GetInstance():GetGoodsVoById(cookOrderDojo.needId)
        local idType = GoodsUtils.GetIdType(goodsVo.id)
        local settingMgr = SettingMgr:GetInstance()
        ---添加奖励显示的逻辑
        if cookOrderDojo.type == 2 then
            ----提交猫鱼的逻辑
            if cookOrderDojo.playerOrderId then
                local havNo = GoodsUtils.GetThingNo(goodsVo.id)
                if checkNumber(havNo) >= checkNumber(cookOrderDojo.requireNum) then
                    ---充足直接提交
                    local consume = {
                        { goodsId = goodsVo.id, num = -checkNumber(cookOrderDojo.requireNum) }
                    }
                    self:OnSubmit(cookOrderDojo.id, havNo, checkNumber(cookOrderDojo.requireNum), consume)
                else
                    GoodsUtils.CheckCurrencyConsume({ goodsId = goodsVo.id, num = checkNumber(cookOrderDojo.requireNum)},function()
                        local consume = {
                            { goodsId = goodsVo.id, num = -checkNumber(cookOrderDojo.requireNum) }
                        }
                        self:OnSubmit(cookOrderDojo.id, havNo, checkNumber(cookOrderDojo.requireNum), consume)
                    end)
                end
            end
            return
        end
        local path = AutoIds.IdSetting3050
        if idType == Constants.IDType.GoodsFish then
            ---如果鱼类
            path = AutoIds.IdSetting3053
        end
        local havNo = GoodsUtils.GetThingNo(goodsVo.id)
        if checkNumber(havNo) >= checkNumber(cookOrderDojo.requireNum) then
            ---充足直接提交
            local consume = {
                { goodsId = goodsVo.id, num = -checkNumber(cookOrderDojo.requireNum) }
            }
            self:OnSubmit(cookOrderDojo.id, havNo, checkNumber(cookOrderDojo.requireNum), consume)
        else
            ---不能直接一次性提交了，需要跳转
            --local row = GoodsConfMgr:GetInstance():GetJumpModuleRow(table.takeFirst(goodsVo.jumpAway))
            --if idType == Constants.IDType.GoodsFish then
            --    GoodsConfMgr:GetInstance():ExecuteJump(row, goodsVo)
            --else
            --    local MaidCoffeeUtils = import("Game.MaidCoffee.MaidCoffeeUtils")
            --    local recipeVo = MaidCoffeeUtils.GetRecipeMakeIDGroupData(goodsVo.id)
            --    GoodsConfMgr:GetInstance():ExecuteJump(row, goodsVo, nil, nil, {recipeVo.refId})
            --end
            local tableFile = settingMgr:Get(path)
            local row = tableFile:GetByPrimaryKey(cookOrderDojo.needId)
            local saleId = checkNumber(row:Get("saleId"))
            local saleNum = checkNumber(row:Get("saleNum"))
            local mySaleNo = GoodsUtils.GetThingNo(saleId)
            saleNum = saleNum * checkNumber(cookOrderDojo.requireNum)
            local vo = GoodsConfMgr:GetInstance():GetGoodsVoById(saleId)
            if vo then
                local subFunc = function()
                    local consume = {
                        { goodsId = saleId, num = -saleNum }
                    }
                    self:OnSubmit(cookOrderDojo.id, havNo, checkNumber(cookOrderDojo.requireNum), consume)
                end
                GameUtils.SecondConfirm(localize('是否使用_num_个_name_立即提交', { _num_ = tostring(saleNum), _name_ = vo.name }), function()
                    if mySaleNo < saleNum then
                        GoodsUtils.CheckCurrencyConsume({ goodsId = saleId, num = saleNum}, subFunc)
                        return
                    end
                    subFunc()
                end, function()
                end)
            end
        end
    end)

    SetButtonAction(self.BtnCookMake,Bind(self,self.OnBtnCookMakeClick))

    self.EventEveryThingChangeEventName = Events.AddListener(Constants.EventNames.EveryThingChangeEventName, Bind(self, self.OnEveryThingChangeEventName))
end

function TakeoutVipOrderPopup:OnEveryThingChangeEventName(id)
    if not isNull(id) then
        return
    end
    self:RefreshNode()
end

function TakeoutVipOrderPopup:RemoveListener()
    Events.RemoveListener(Constants.EventNames.EveryThingChangeEventName, self.EventEveryThingChangeEventName)
    self.EventEveryThingChangeEventName = nil
end

function TakeoutVipOrderPopup:OnSubmit(id, have, need, consume)
    GameUtils.Request(Interfaces.MaidCoffeeTakeoutVipOrderSubmit, { id = id }, function(request, response)
        if checkNumber(response.errCode) == 0 then
            self.data.isSubmit = true
            GoodsUtils.DrawRewards(consume)
            ---去除消耗
            local rewards = checkTable(response.data.rewards)
            if #rewards > 0 then
                GoodsUtils.DrawRewards(rewards, true)
                ---去除消耗
                UIModule.OpenDialog(
                        {
                            id = Constants.UITypeIds.UICommonRewardPop,
                            parameters = { rewards = rewards }
                        }
                )
            end
            Events.Broadcast(Constants.EventNames.EVENT_TAKEOUT_VIP_DATA_CHANGED, id)
            UIModule.CloseDialog(self.controller)
        end
    end)
end

function TakeoutVipOrderPopup:OnInitialize()
    ---@type Engine.Lib.CoWait
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        ---@type Engine.UI.UIArgument
        local argument = self.controller.Argument
        if argument.parameters then
            self.data = argument.parameters
            self:RefreshNode()
        end
    end))
    return coWait
end

function TakeoutVipOrderPopup:RefreshNode()
    local cookOrderDojo = self.data
    if cookOrderDojo then
        local goodsVo = GoodsConfMgr:GetInstance():GetGoodsVoById(cookOrderDojo.needId)
        if goodsVo then
            ---@type GoodNodeMB
            local env = CfUtils.GetLuaScr(self.CookGoodNode.gameObject, GoodNodePath)
            if not isNull(env) then
                env:Reload(
                        {
                            goodsId = goodsVo.id, isShowNo = false,
                        }
                )
                env:SetClickCallback(function()
                    if isTable(goodsVo) then
                        ---显示通用tips
                        GameUtils.ShowCommonGoodsTipsBoard(self.CookGoodNode.transform.parent.gameObject, goodsVo.id, true)
                    end
                end)
            end
            --      <color=#ff2ea9>4</color>/8
            local no = GoodsUtils.GetThingNo(goodsVo.id)
            self.TextName.text = tostring(goodsVo.name)
            local settingMgr = SettingMgr:GetInstance()
            KTool.SetActive(self.CommonBtnConsumePop.gameObject, no < checkNumber(cookOrderDojo.requireNum))
            if no >= checkNumber(cookOrderDojo.requireNum) then
                self.TextNumber.text = no .. '/' .. tostring(cookOrderDojo.requireNum)
                ---充足的情况下
                self.FontStyleButton:GetComponent("FontStyleButton"):ResetFontStyle("B6", localize("提交"))
            else
                self.TextNumber.text = string.format_color_tag(no, "#ff2ea9") .. '/' .. tostring(cookOrderDojo.requireNum)
                ---不足的情况下显示快速提交
                self.FontStyleButton:GetComponent("FontStyleButton"):ResetFontStyle("B25", localize("快速提交"))
                local path = AutoIds.IdSetting3050
                local idType = GoodsUtils.GetIdType(goodsVo.id)
                if idType == Constants.IDType.GoodsFish then
                    ---如果鱼类
                    path = AutoIds.IdSetting3053
                end
                local tableFile = settingMgr:Get(path)
                local row = tableFile:GetByPrimaryKey(cookOrderDojo.needId)
                local saleId = checkNumber(row:Get("saleId"))
                local saleNum = checkNumber(row:Get("saleNum"))
                saleNum = saleNum * checkNumber(cookOrderDojo.requireNum)
                local consumeEnv = CfUtils.GetLuaScr(self.CommonBtnConsumePop, "Game.UI.Common.CommonBtnConsumePop")
                if consumeEnv then
                    consumeEnv:RefreshUI(saleId, saleNum, false)
                end
            end
            ---添加奖励显示的逻辑
            if cookOrderDojo.type == 2 then
                ---如果是提交鱼王
                self.TextTitle.text = localize('提交猫鱼')
                local goodsId, num
                if cookOrderDojo.rewardId and cookOrderDojo.rewardId > 0 then
                    goodsId = cookOrderDojo.rewardId
                    num = cookOrderDojo.rewardNum
                else
                    ---@type TableML.TableFile
                    local tableFile = settingMgr:Get(AutoIds.IdSetting3054)
                    if cookOrderDojo.playerOrderId then
                        ---@type TableML.TableFileRow
                        local row = tableFile:GetByPrimaryKey(cookOrderDojo.playerOrderId)
                        goodsId = checkNumber(row:Get("fishRewardId"))
                        num = checkNumber(row:Get("fishRewardNum"))
                    end
                end
                ---@type GoodNodeMB
                local env = CfUtils.GetLuaScr(self.GoodNode.gameObject, GoodNodePath)
                if not isNull(env) then
                    env:Reload(
                            {
                                goodsId = goodsId, isShowNo = true,
                                text = "x" .. num
                            }
                    )
                    env:SetClickCallback(function()
                        local vo = GoodsConfMgr:GetInstance():GetGoodsVoById(goodsId)
                        if isTable(vo) then
                            GameUtils.ShowCommonTipsBoard(self.GoodNode.gameObject, vo.name, vo.desc, vo.quality, vo.id)
                        end
                    end)
                end
                return
            end
            local idType = GoodsUtils.GetIdType(goodsVo.id)
            local path = AutoIds.IdSetting3050
            if idType == Constants.IDType.GoodsFish then
                ---如果鱼类
                path = AutoIds.IdSetting3053
                self.TextTitle.text = localize('提交猫鱼')
                self.BtnCookMake:GetComponent("FontStyleButton"):ResetFontStyle("B6", localize("前往渔场"))
            else
                self.BtnCookMake:GetComponent("FontStyleButton"):ResetFontStyle("B6", localize("料理制作"))
                self.TextTitle.text = localize('提交料理')
            end
            -----@type TableML.TableFile
            --local tableFile = settingMgr:Get(path)
            -----@type TableML.TableFileRow
            --local row = tableFile:GetByPrimaryKey(cookOrderDojo.needId)
            --local goodsId = checkNumber(row:Get("priceId"))
            local goodsId = checkNumber(cookOrderDojo.rewardId)
            local num = tostring(checkNumber(cookOrderDojo.rewardNum))
            ---@type GoodNodeMB
            local env = CfUtils.GetLuaScr(self.GoodNode.gameObject, GoodNodePath)
            if not isNull(env) then
                env:Reload(
                        {
                            goodsId = goodsId, isShowNo = true,
                            text = "x" .. num
                        }
                )
            end
        end
    end
end

function TakeoutVipOrderPopup:OnBtnCookMakeClick()
    local cookId = self.data.needId
    local idType = GoodsUtils.GetIdType(cookId)
    if idType == Constants.IDType.RestaurantCookingGoods then
        local t = { }
        table.insert(t, { goodsId = cookId, num = checkNumber(self.data.requireNum) })
        UIModule.OpenDialog({ id = Constants.UITypeIds.UIMaidCoffeeCookingMainDialog, parameters = { type = MaidCoffeeConstants.CookingType.VipOrder,
                                                                                                     data = t,
                                                                                                     cb = function()
                                                                                                         self:RefreshNode()
                                                                                                     end } })
    elseif idType == Constants.IDType.GoodsFish then
        local goodsVo = GoodsConfMgr:GetInstance():GetGoodsVoById(cookId)
        if next(goodsVo.jumpAway)  then
            local row = GoodsConfMgr:GetInstance():GetJumpModuleRow(goodsVo.jumpAway[1])
            GoodsConfMgr:GetInstance():ExecuteJump(row, goodsVo)
        end
    end
end

function TakeoutVipOrderPopup:OnFinalize()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        self:RemoveListener()
        self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
        self:Delete()
        self = nil --lua层的gc需要
    end))
    return coWait
end

return TakeoutVipOrderPopup